{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "실행 계획에서 확인한 병목을 근거로 느린 조회 쿼리의 개선 방향을 정한 판단을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 느렸던 상황",
          "task": "실행 계획에서 병목을 찾아 쿼리의 개선 방향을 정하는 것",
          "action": "실행 계획의 조회 및 조인 특성을 해석하고, 확인한 병목에 맞춰 개선 방향을 선택한 판단을 설명한다.",
          "result": "실행 계획에서 확인한 사실과 선택한 개선 방향의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "실행 계획을 근거로 신고 목록 조회 쿼리의 개선 방향을 정한 판단",
          "병목의 근거로 삼은 테이블 접근 방식이나 조인 처리 특성",
          "확인한 병목과 인덱스 추가 또는 조인 정리 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 실행 계획에서 무엇을 보고 쿼리의 개선 방향을 정하셨어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 접근 방식이나 조인 처리 특성을 구체적으로 설명한다.",
            "해당 특성이 조회 병목이라고 판단한 이유를 설명하고, 인덱스 추가 또는 조인 정리 방향과 타당하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실행 계획을 바탕으로 개선 방향을 정했다는 설명은 있으나, 병목으로 해석한 접근 방식이나 조인 특성이 구체적이지 않다.",
            "확인한 병목과 선택한 개선 방향의 연결을 일부 설명하지만 판단 근거가 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "실행 계획에서 무엇을 확인했는지 설명하지 못하거나 병목에 대한 해석이 타당하지 않다.",
            "인덱스 추가나 조인 정리를 했다는 사실만 말하고, 해당 방향을 선택한 근거를 제시하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "배포 후 발생한 알림 중복 발송 오류에서 시간순 로그의 흐름을 해석해 원인을 좁힌 판단을 검증한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의를 받은 상황",
          "task": "시간순으로 모은 로그를 통해 중복 발송의 원인을 좁히는 것",
          "action": "로그에 나타난 실행 흐름을 설명하고, 그 흐름이 서버 두 대의 스케줄러 중복 실행을 가리킨다고 판단한 이유를 제시한다.",
          "result": "로그에서 관찰한 사실과 오류 원인에 대한 판단의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "시간순 로그의 실행 흐름을 근거로 오류 원인을 좁힌 판단",
          "중복 발송과 관련해 로그에서 실제로 확인한 실행 시점 및 서버별 실행 흔적",
          "관찰한 로그 흐름이 스케줄러 중복 실행을 가리킨다고 해석한 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 추적하셨던데요, 시간순으로 모은 로그에서 어떤 실행 흐름을 보고 오류 원인을 좁히셨어요?",
      "answerTip": "기억나는 장면을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 실행 시점과 서버별 실행 흔적을 바탕으로 중복 발송 관련 흐름을 구체적으로 설명한다.",
            "그 흐름이 스케줄러 중복 실행을 원인으로 가리키는 이유를 논리적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "로그에서 서버별 스케줄러 실행을 확인했다는 핵심 근거는 제시하지만 실행 흐름에 대한 설명이 일부 불명확하다.",
            "로그 흐름과 원인 판단을 연결하지만, 중복 실행으로 해석한 이유가 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "스케줄러 중복 실행이라는 결론만 제시하고 로그에서 확인한 실행 흐름을 설명하지 못한다.",
            "제시한 로그 내용이 원인 판단을 뒷받침하지 못하거나 로그 해석에 타당한 연결이 없다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "여러 사용자에게서 수집한 요청을 목적과 범위에 따라 묶어 구현 가능한 요구사항으로 구체화하는 판단을 확인한다. 질문은 인터뷰 요청을 요구사항으로 정리한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳의 인터뷰 요청을 수집한 상황이다.",
          "task": "여러 요청의 의미와 범위를 정리해 요구사항 정의서에 담을 요구사항으로 구체화해야 했다.",
          "action": "요청의 목적과 적용 범위를 기준으로 관련 요청을 묶고, 그 묶음을 구체적인 요구사항으로 정리한 판단을 설명한다.",
          "result": "수집한 요청이 어떤 기준을 거쳐 어떤 요구사항으로 정리되었는지 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "인터뷰 요청을 묶어 요구사항으로 정리한 기준",
          "그 기준을 적용한 실제 요청의 내용과 목적 또는 적용 범위",
          "요청을 묶은 기준과 정의서에 정리한 요구사항 사이의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰하셨던데요, 인터뷰에서 나온 요청은 어떤 기준으로 묶어 요구사항으로 정리하셨어요?",
      "answerTip": "한 사례를 중심으로 차근차근 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "요청을 묶은 기준이 요청의 목적이나 적용 범위에 근거해 구체적으로 설명된다.",
            "실제 인터뷰 요청의 내용이 제시되고 해당 기준을 적용한 이유가 명확하다.",
            "수집한 요청이 정의서의 구체적인 요구사항으로 정리된 연결이 일관되게 드러난다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요청을 묶은 기준은 제시하지만 목적이나 적용 범위에 관한 설명이 제한적이다.",
            "실제 요청과 정리된 요구사항은 확인되지만 둘 사이의 연결이 일부 생략되어 있다."
          ]
        },
        "poor": {
          "criteria": [
            "요청을 정리한 기준을 제시하지 못하거나 인터뷰 내용을 그대로 나열하는 데 그친다.",
            "실제 요청과 정의서의 요구사항 사이의 연결을 확인하기 어렵다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 실제 화면 동작으로 구체화하는 설계 판단을 확인한다. 질문은 화면설계서에 담은 예외 대응 동작 중 가장 고민한 결정 하나에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예외 상황을 포함한 화면설계서 28장을 작성한 상황이다.",
          "task": "특정 예외 상황에서 화면이 보여 줄 상태나 동작을 구체적으로 결정해야 했다.",
          "action": "가장 고민한 화면 동작 결정 하나를 선택하고, 해당 예외 조건과 화면 흐름을 근거로 설계 판단을 설명한다.",
          "result": "예외 상황에서 화면이 실제로 어떤 상태나 동작을 보이도록 설계했는지 분명하게 드러난다."
        },
        "expectedEvidence": [
          "예외 상황에 대응하는 화면 동작에서 가장 고민한 결정 하나",
          "해당 결정이 필요했던 구체적인 예외 조건과 화면 맥락",
          "예외 조건을 화면 상태나 동작으로 연결한 설계 근거"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 화면설계서 28장을 작성하셨던데요, 그중 예외 상황에 대응하는 화면 동작에서 가장 고민하신 결정은 뭐였어요?",
      "answerTip": "당시 장면을 떠올리며 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "고민한 결정이 구현할 화면 상태나 동작 하나로 구체적으로 제시된다.",
            "해당 동작이 필요한 예외 조건과 화면 맥락이 명확하다.",
            "예외 조건에 비추어 그 화면 동작을 선택한 설계 근거가 일관되게 설명된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "예외 상황과 관련된 화면 동작 결정은 제시하지만 적용 조건이나 화면 맥락이 일부 불명확하다.",
            "설계 근거는 확인되지만 예외 조건과 선택한 동작 사이의 연결이 충분히 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "고민한 화면 동작 결정을 제시하지 못하거나 화면설계 도구와 작성 분량만 설명한다.",
            "예외 조건과 화면 상태 또는 동작의 연결을 확인하기 어렵다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "투약 전 처방 확인에서 발견한 이상을 근거로 투약을 보류할 수 있는지 검증한다. 진통제 용량을 확인한 사실과 투약 중단 판단 사이의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 입력된 상황",
          "task": "해당 처방대로 투약을 진행해도 되는지 판단해야 했던 상황",
          "action": "실제로 확인한 처방 내용과 비교 근거를 바탕으로, 확인 없이 투약해서는 안 된다고 판단한 이유를 설명함",
          "result": "투약을 멈춘 판단이 어떤 확인 사실에 근거했는지 구체적으로 드러남"
        },
        "expectedEvidence": [
          "당시 투약을 멈춰야 한다고 판단한 구체적인 근거",
          "처방 용량의 이상을 판단하는 데 실제로 확인하거나 비교한 정보",
          "확인된 용량 차이가 처방 재확인 전 투약 보류로 이어진 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방이 평소 용량의 두 배였던 적이 있다고 하셨는데요, 당시 투약을 멈춰야 한다고 판단하신 근거는 뭐였어요?",
      "answerTip": "당시 상황을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약 중단 판단의 근거를 실제로 확인하거나 비교한 처방 정보와 함께 구체적으로 설명한다.",
            "용량 차이를 단순한 인상으로 넘기지 않고, 재확인 전에는 투약을 보류해야 한다고 판단한 이유를 명확하게 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 멈췄다는 핵심 근거는 제시하지만, 실제 확인하거나 비교한 정보가 구체적이지 않다.",
            "재확인이 필요했다는 설명은 있으나, 확인된 차이와 투약 보류 판단의 연결이 충분히 드러나지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈췄다는 사실만 반복하며 판단의 근거나 확인한 정보를 제시하지 못한다.",
            "나중에 입력 오류로 확인됐다는 결과만 설명하고, 당시 투약을 보류한 이유는 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태를 이전 상태와 비교해 변화로 판단하고 간호 기록에 반영할 수 있는지 검증한다. 실제 병동 업무에서 상태 변화를 기록한 판단 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동에서 수술 전후 환자의 활력징후와 통증을 관찰하고 기록하던 상황",
          "task": "관찰한 내용을 바탕으로 간호 기록에 남길 환자 상태 변화를 판단해야 했던 상황",
          "action": "관찰값과 환자의 호소를 이전 기록이나 상태와 비교해 기록에 반영한 기준을 설명함",
          "result": "어떤 관찰 근거로 상태 변화를 판단해 기록했는지가 구체적으로 드러남"
        },
